     *
     * @param                  Modulo $v
     * @return TipoControl The current object (for fluent API support)
     * @throws PropelException
     */
    public function setModulo(Modulo $v = null)
    {
        if ($v === null) {
            $this->setModuloId(NULL);
        } else {
            $this->setModuloId($v->getModuloId());
        }

        $this->aModulo = $v;

        // Add binding for other direction of this n:n relationship.
        // If this object has already been added to the Modulo object, it will not be re-added.
        if ($v !== null) {
            $v->addTipoControl($this);
        }


        return $this;
    }


    /**
