     *
     * This does not modify the database; however, it will remove any associated objects, causing
     * them to be refetched by subsequent calls to accessor method.
     *
     * @return TipoControl The current object (for fluent API support)
     * @see        addNovedadess()
     */
    public function clearNovedadess()
    {
        $this->collNovedadess = null; // important to set this to null since that means it is uninitialized
        $this->collNovedadessPartial = null;

        return $this;
    }

    /**
