     */
    public function resetPartialNovedadess($v = true)
    {
        $this->collNovedadessPartial = $v;
    }

    /**
     * Initializes the collNovedadess collection.
     *
     * By default this just sets the collNovedadess collection to an empty array (like clearcollNovedadess());
     * however, you may wish to override this method in your stub class to provide setting appropriate
     * to your application -- for example, setting the initial array to the values stored in database.
     *
     * @param boolean $overrideExisting If set to true, the method call initializes
     *                                        the collection even if it is not empty
     *
     * @return void
     */
    public function initNovedadess($overrideExisting = true)
    {
        if (null !== $this->collNovedadess && !$overrideExisting) {
            return;
        }
        $this->collNovedadess = new PropelObjectCollection();
        $this->collNovedadess->setModel('Novedades');
    }

    /**
     * Gets an array of Novedades objects which contain a foreign key that references this object.
     *
     * If the $criteria is not null, it is used to always fetch the results from the database.
     * Otherwise the results are fetched from the database the first time, then cached.
     * Next time the same method is called without $criteria, the cached collection is returned.
     * If this TipoControl is new, it will return
     * an empty collection or the current collection; the criteria is ignored on a new object.
     *
     * @param Criteria $criteria optional Criteria object to narrow the query
     * @param PropelPDO $con optional connection object
     * @return PropelObjectCollection|Novedades[] List of Novedades objects
     * @throws PropelException
     */
    public function getNovedadess($criteria = null, PropelPDO $con = null)
    {
        $partial = $this->collNovedadessPartial && !$this->isNew();
        if (null === $this->collNovedadess || null !== $criteria  || $partial) {
            if ($this->isNew() && null === $this->collNovedadess) {
                // return empty collection
                $this->initNovedadess();
            } else {
                $collNovedadess = NovedadesQuery::create(null, $criteria)
                    ->filterByTipoControl($this)
                    ->find($con);
                if (null !== $criteria) {
                    if (false !== $this->collNovedadessPartial && count($collNovedadess)) {
                      $this->initNovedadess(false);

                      foreach ($collNovedadess as $obj) {
                        if (false == $this->collNovedadess->contains($obj)) {
                          $this->collNovedadess->append($obj);
                        }
                      }

                      $this->collNovedadessPartial = true;
                    }

                    $collNovedadess->getInternalIterator()->rewind();

                    return $collNovedadess;
                }

                if ($partial && $this->collNovedadess) {
                    foreach ($this->collNovedadess as $obj) {
                        if ($obj->isNew()) {
                            $collNovedadess[] = $obj;
                        }
                    }
                }

                $this->collNovedadess = $collNovedadess;
                $this->collNovedadessPartial = false;
            }
        }

        return $this->collNovedadess;
    }

    /**
     * Sets a collection of Novedades objects related by a one-to-many relationship
     * to the current object.
     * It will also schedule objects for deletion based on a diff between old objects (aka persisted)
     * and new objects from the given Propel collection.
     *
     * @param PropelCollection $novedadess A Propel collection.
     * @param PropelPDO $con Optional connection object
     * @return TipoControl The current object (for fluent API support)
     */
    public function setNovedadess(PropelCollection $novedadess, PropelPDO $con = null)
    {
        $novedadessToDelete = $this->getNovedadess(new Criteria(), $con)->diff($novedadess);


        $this->novedadessScheduledForDeletion = $novedadessToDelete;

        foreach ($novedadessToDelete as $novedadesRemoved) {
            $novedadesRemoved->setTipoControl(null);
        }

        $this->collNovedadess = null;
        foreach ($novedadess as $novedades) {
            $this->addNovedades($novedades);
        }

        $this->collNovedadess = $novedadess;
        $this->collNovedadessPartial = false;

        return $this;
    }

    /**
     * Returns the number of related Novedades objects.
     *
     * @param Criteria $criteria
     * @param boolean $distinct
     * @param PropelPDO $con
     * @return int             Count of related Novedades objects.
     * @throws PropelException
     */
    public function countNovedadess(Criteria $criteria = null, $distinct = false, PropelPDO $con = null)
    {
        $partial = $this->collNovedadessPartial && !$this->isNew();
        if (null === $this->collNovedadess || null !== $criteria || $partial) {
            if ($this->isNew() && null === $this->collNovedadess) {
                return 0;
            }

            if ($partial && !$criteria) {
                return count($this->getNovedadess());
            }
            $query = NovedadesQuery::create(null, $criteria);
            if ($distinct) {
                $query->distinct();
            }

            return $query
                ->filterByTipoControl($this)
                ->count($con);
        }

        return count($this->collNovedadess);
    }

    /**
     * Method called to associate a Novedades object to this object
     * through the Novedades foreign key attribute.
     *
     * @param    Novedades $l Novedades
     * @return TipoControl The current object (for fluent API support)
     */
    public function addNovedades(Novedades $l)
    {
        if ($this->collNovedadess === null) {
            $this->initNovedadess();
            $this->collNovedadessPartial = true;
        }

        if (!in_array($l, $this->collNovedadess->getArrayCopy(), true)) { // only add it if the **same** object is not already associated
            $this->doAddNovedades($l);

            if ($this->novedadessScheduledForDeletion and $this->novedadessScheduledForDeletion->contains($l)) {
                $this->novedadessScheduledForDeletion->remove($this->novedadessScheduledForDeletion->search($l));
            }
        }

        return $this;
    }

    /**
     * @param	Novedades $novedades The novedades object to add.
     */
    protected function doAddNovedades($novedades)
    {
        $this->collNovedadess[]= $novedades;
        $novedades->setTipoControl($this);
    }

    /**
     * @param	Novedades $novedades The novedades object to remove.
     * @return TipoControl The current object (for fluent API support)
     */
    public function removeNovedades($novedades)
    {
        if ($this->getNovedadess()->contains($novedades)) {
            $this->collNovedadess->remove($this->collNovedadess->search($novedades));
            if (null === $this->novedadessScheduledForDeletion) {
                $this->novedadessScheduledForDeletion = clone $this->collNovedadess;
                $this->novedadessScheduledForDeletion->clear();
            }
            $this->novedadessScheduledForDeletion[]= clone $novedades;
            $novedades->setTipoControl(null);
        }

        return $this;
    }


